package com.hbm.item.designator.advanced;
import java.util.List;import net.minecraft.world.item.ItemStack;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.registries.*;
public final class AdvancedDesignatorContent{private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");public static final DeferredItem<RangeDesignatorItem> RANGE=ITEMS.register("designator_range",RangeDesignatorItem::new);public static final DeferredItem<ManualDesignatorItem> MANUAL=ITEMS.register("designator_manual",ManualDesignatorItem::new);public static void register(IEventBus bus){ITEMS.register(bus);bus.addListener(ManualDesignatorControl::register);}public static List<ItemStack> creativeStacks(String tab){return tab.equals("missile")?List.of(new ItemStack(RANGE.get()),new ItemStack(MANUAL.get())):List.of();}private AdvancedDesignatorContent(){}}
